// Renders a protocol of seed/protocols.json as a handbook entry (seed/handbook/protocol-<id>.md), so protocols are
// searchable and readable in the handbook. Generated by scripts/build-handbook-index.ts — the JSON stays the single
// source of the step wording; a test fails if a generated file is stale.
import { PROTOCOL_ORDER } from './protocolIds';
import type { Protocol } from './types';

/** Every source id a protocol relies on: row, trigger and steps (unique, first-seen order). */
export function protocolSourceIds(p: Protocol): string[] {
  return [...new Set([...p.sourceIds, ...p.triggerSourceIds, ...p.steps.flatMap((s) => s.sourceIds)])];
}

export function protocolEntryId(p: Pick<Protocol, 'id'>): string {
  return `protocol-${p.id}`;
}

export function protocolFileName(p: Pick<Protocol, 'id'>): string {
  return `${protocolEntryId(p)}.md`;
}

const list = (xs: readonly string[]): string => `[${xs.join(', ')}]`;

export function renderProtocolMarkdown(p: Protocol): string {
  const sources = protocolSourceIds(p);
  const steps = p.steps.map((s, i) => {
    const tags = s.tag === 'source' ? s.sourceIds.map((id) => `[${id}]`).join(' ') : '[demo wording]';
    return `${i + 1}. ${s.text} ${tags}`;
  });
  const sourceLines =
    sources.length > 0
      ? sources.map((id) => `- [${id}]`)
      : ['No published source: every step is demo wording.'];
  return [
    '---',
    '# Generated from seed/protocols.json by scripts/build-handbook-index.ts. Do not edit by hand.',
    `id: ${protocolEntryId(p)}`,
    `title: ${p.title}`,
    'category: protocols',
    `order: ${PROTOCOL_ORDER[p.id]}`,
    `protocolId: ${p.id}`,
    `signalIds: ${list(p.relatedSignalIds)}`,
    `keywords: ${list(p.keywords)}`,
    `sourceIds: ${list(sources)}`,
    `summary: ${p.summary}`,
    '---',
    '',
    '## When ARGUS suggests it',
    '',
    p.triggerPlain,
    '',
    '## Steps',
    '',
    ...steps,
    '',
    '## Sources',
    '',
    ...sourceLines,
    '',
  ].join('\n');
}
